"""Render the protocol's §11 paragraph (inputs validated before the lock) and the power/projection summary from
outputs/study2_v0.1/VALIDATION.json and INPUTS.json, so that every number in the protocol's §11 is generated, not retyped
(rule A4.1). Prints Markdown to stdout; the conductor pastes it into research/STUDY2_PROTOCOL_v0.1.md between the §11 markers.
Usage: .venv/bin/python research/study2/s2_protocol_fill.py [--N <N>] [--K <K>]
"""
import json, pathlib, sys
import numpy as np
ROOT = pathlib.Path(__file__).resolve().parents[2]
V = json.loads((ROOT / "outputs/study2_v0.1/VALIDATION.json").read_text())
a = sys.argv[1:]; N = int(a[a.index("--N") + 1]) if "--N" in a else None; K = int(a[a.index("--K") + 1]) if "--K" in a else None


def f(x, d=3):
    return "nan" if x is None else (f"{x:.{d}f}" if isinstance(x, float) else str(x))


fx = V["fixtures"]; ck = V["checks"]["token_cache"]; tm = V["timing"]; pj = V["projection"]; pw = V["power"]
tc_cells = ck.get("cells", {})
lines = []
lines.append(f"`s2_validate.py` → `outputs/study2_v0.1/VALIDATION.json` (run {V['date_utc']}; the synthetic validation cells in `{V['validation_dir']}/`, retained and git-ignored, with the pilot analysis file beside the directory). **No per-key level on real text is computed before the lock**; the validation uses synthetic tokens (a Zipf law at V = 128,256) with validation keys for the implementation checks and the timing, and reads only key-free quantities, sizes and digests of the real chains.")
lines.append(f"**(a) The token cache.** Every one of the {2 * len(tc_cells)} arrays matches its manifest digest, shape, dtype and id range; the pools and draws recomputed from the units metadata reproduce every pool digest, seed and ids digest; the seal's partition, units and manifest digests equal the current ones; the tokenizer provenance equals `counts.json`'s: all_ok = {ck['all_ok']}. Pool sizes (eligible under both tokenizers): " + "; ".join(f"{t.rsplit('_', 1)[0].replace('_', '/')}@{t.rsplit('_', 1)[1]} {c['pool_size_recomputed']:,}" for t, c in tc_cells.items()) + ".")
g = fx["per_text_closed_form_vs_study1_closed_form"]; f6 = fx["closed_form_per_text_thresholds"]; gt = fx["gamma_threshold_exact"]; ig = fx["identity_gumbel_20000_keys"]; ik = fx["identity_kgw_indep_20000_keys"]; se = fx["gumbel_known_mean_se_calibration"]; fh = fx["fixed_h0_real_V"]; ss = fx["simulated_shift"]; hv = fx["heavy_tuple_cell_h0_raw_support50"]; cb = fx["crossed_bootstrap_median_coverage_null"]
lines.append(f"**(b) Fixtures with validation keys on synthetic chains.** The Study 1 code path is reproduced field for field at 30 text-bootstrap resamples on an N = 600, L = 256 synthetic chain at the real vocabulary size (`study1_fields_identical`: {fx['study1_fields_identical']['ok']}; the integer level counts equal the levels × N_eff; with the production 5 resamples every deterministic quantity is unchanged ({fx['study1_fields_identical']['production_B_preserves_deterministic_quantities']}) while the Monte Carlo intervals' realisations differ, R05 F5); the per-text-threshold closed form equals Study 1's closed form in every α of that chain (largest |Δsd| {max(g['abs_diff_sd_by_alpha'].values()):.1e}) and at σ² ∈ {{0, 10⁻⁶, 10⁻³, 0.5, 1}} for one threshold (largest |Δsd| {max(x['abs_diff_sd'] for x in f6['vs_study1_closed_form'].values()):.1e}), agrees with the discrete-node quadrature at an ordinary σ² with {f6['vs_quadrature_ordinary_sigma']['n_distinct_thresholds']} distinct Gamma thresholds (|Δsd| {f6['vs_quadrature_ordinary_sigma']['abs_diff_sd']:.1e}) and with Monte Carlo at σ² → 0 with varying thresholds (at σ² = 10⁻⁶: SD {f6['vs_monte_carlo_tiny_sigma']['1e-06']['mc_sd_pop']:.5f} by {f6['vs_monte_carlo_tiny_sigma']['1e-06']['mc_draws']:,} draws against {f6['vs_monte_carlo_tiny_sigma']['1e-06']['closed_sd_pop']:.5f} closed; the retired Gaussian quadrature gave 0.113 against 0.0995 at σ = 0, R05 F6); the exact Gamma(M, 1) threshold gives the nominal level by simulation at M ∈ {{64, 250, 1,000}} and α ∈ {{0.01, 0.05}} (200,000 draws each; all within 3 binomial SEs: {gt['ok']}); with 20,000 validation keys the Gumbel identity reproduces the across-key variance of the per-key mean score (ratio {ig['ratio']:.4f}; mean score {ig['mean_sbar']:.5f} against 1) and the KGW independent identity the variance of q̂ (ratio {ik['ratio']:.4f}); the Exp(1) fourth-moment SE of the known-mean estimator is calibrated over 200 disjoint 100-key subsamples (SD of the standardised deviation {se['sd_of_standardised_deviation']:.2f}, largest magnitude {se['max_abs']:.2f}); the fixed-size colouring at h = 0 at V = 128,256 (one class; {fh['queried_tokens']:,} covered tokens; 2,000 keys) gives a marginal green fraction {fh['marginal_green_fixed']:.4f} against g = {fh['g']:.4f} and an observed fixed/independent variance ratio {fh['observed_ratio']:.4f} against the exact (V − 1/C_cond)/(V − 1) = {fh['exact_ratio']:.4f} (reduction {100 * fh['reduction']:.2f}%; both variances within 10% of their identities: {fh['ok']}); the simulated shift's variance matches ρ̄ (ratio {ss['var_matches_rho_bar']['ratio']:.4f}), its heavy-tuple share is {ss['heavy_share']:.3f} on the Zipf chain, and on uniform weights it is Gaussian (skew {ss['uniform_weights_gaussian_limit']['skew']:.3f}, excess kurtosis {ss['uniform_weights_gaussian_limit']['excess_kurtosis']:.3f}); on a heavy-tuple chain (50 tokens of V, raw rule, h = 0, 2,000 texts, 3,000 keys) the observed SD is {100 * hv['0.01']['sd_obs']:.2f} pp against {100 * hv['0.01']['pred_gaussian_shift']:.2f} pp (Gaussian shift) and {100 * hv['0.01']['pred_simulated_shift']:.2f} pp (simulated shift) at α = 0.01 (ratios {hv['0.01']['ratio_gaussian']:.3f} and {hv['0.01']['ratio_simulated']:.3f}; shift skew {hv['0.01']['shift_skew']:.2f}); the crossed bootstrap's 95% interval of the median key level covers α in {cb['coverage_of_alpha_by_median_interval']:.2f} of 40 key-independent tables (a sanity check).")
s2t = fx["s2_thresholds"]; kk = str(K or V.get("grid_K", 1000))
lines.append(f"**S2's power table** (`s2_thresholds`): " + "; ".join(f"K = {Kx}: dead detector flaggable iff μ_a > {t['dead_detector_flaggable_iff_mu_above']:.4f}; μ_a = 0.05 flags above {t['mu_0.05']['flag_above']:.4f} or below {f(t['mu_0.05']['flag_below'], 4)}; μ_a = 0.01 above {t['mu_0.01']['flag_above']:.4f} or below {f(t['mu_0.01']['flag_below'], 4)}; μ_a = 0.001 above {t['mu_0.001']['flag_above']:.4f}" for Kx, t in s2t.items()) + f". The check count if every distinct-rule cell is live: {fx['s2_check_count']['distinct_rule_cells']} cells × {fx['s2_check_count']['alphas']} levels = {fx['s2_check_count']['distinct_rule_cells'] * fx['s2_check_count']['alphas']}, union bound {fx['s2_check_count']['union_bound_if_all_live']:.2e}.")
lk = fx["lock"]; kp = fx["key_policy"]; pv = fx["provenance_slot"]; inv = fx.get("analyzer_inventory", {})
lines.append(f"**(c)–(f) Fixtures (all as required).** The key policy accepts the Study 2 range and the validation namespace and refuses the reserved range, Study 1's range, the audit's 0–999 and keys below each namespace ({kp['all_ok']}); the lock schema accepts the complete canonical lock under a copied root and refuses {len(lk['refused'])} variants (among them a missing `approved_by`, `final: true`, `before_outcomes: false`, a non-ISO or early date, the wrong study, non-canonical protocol, validation, inputs, manifest and grid paths, checkpoint R03, the R04 resolution, a tampered, non-hex, missing or extra digest, a key-record mismatch, a reserved key start, a wrong review digest and a manifest with fewer texts than the grid's N; accepted: {lk['accepted']}); provenance: a matching cell is reusable and a foreign provenance, the same provenance at another slot and a body that disagrees with its slot are refused ({pv['ok']}); the analyzer refuses an inventory with one cell missing, an extra file, a stale provenance, a same-provenance wrong-cell copy, a missing α, K − 1 level counts, a missing or zero N_eff, a marker at a live slot, negative, fractional or over-range counts, counts contradicting the stored summary, a nesting violation with consistent summaries, a deployer cell without its crossed block, and study mode without a lock (which now reaches its own branch: {inv.get('study_mode_without_lock_reaches_lock_branch')}), and accepts the complete pilot inventory ({inv.get('ok')}); the language-disparity cases (identical positive, all zero, one zero language, the production selection of exactly the six @256 Wikipedia cells) behave as §7 pre-states ({fx['language_disparity_cases']['ok']}); the synthetic pilot exercises S1 ({fx['pilot_rule_paths_exercised']['S1_candidates']} candidates), S4 ({fx['pilot_rule_paths_exercised']['S4_chains']} chains), S5 ({fx['pilot_rule_paths_exercised']['S5_chains']} chains) and the deployer paths ({fx['pilot_rule_paths_exercised']['deployer_rows']} rows).")
vr = tm.get("validation_run", {}); rs = tm["real_sized_synthetic_chain"]; pb = tm.get("production_scale_runner_probe", {})
lines.append(f"**(g) The timed validation run.** The synthetic grid ({vr.get('expected_cells')} cells: h ∈ {{0, 1, 2}}, L ∈ {{64, 256}}, both families, both γ, the fixed colouring at h = 0, K = {vr.get('K_validation')}, N = 600) ran in {vr.get('seconds')} s (return code {vr.get('returncode')}; {vr.get('n_cells')} cells; mean cell file {vr.get('cell_file_kb_mean')} KB at K = {vr.get('K_validation')}) and the analyzer executed in pilot mode (return code {vr.get('analyzer_returncode')}; the conductor read the execution status and the counts only: S2 {vr.get('pilot_counts_only', {}).get('S2')}, S3 {vr.get('pilot_counts_only', {}).get('S3')}).")
proj = "; ".join(f"{k.replace('_', ', ')}: **{v['hours']} h**" + ("" if v["within_budget"] else " (over budget)") for k, v in pj.items() if k.startswith("N"))
pts = rs["cell_statistics_points"]; cf = rs["cell_statistics_fit"]
lines.append(f"**(h) The cost model.** A real-sized synthetic chain (N = {rs['N']:,}, L = 1,024, h = 4, |D| = {rs['n_tuples']:,}) builds in {rs['build_seconds']} s; at K = {rs['K']} the hash takes {rs['hash_seconds']} s ({rs['hash_seconds_per_tuple_key']:.2e} s per tuple·key) and the three rules' products {rs['product_seconds']} s ({rs['product_seconds_per_nnz_key_scoring']:.2e} s per nnz·key·scoring; nnz {rs['nnz_three_rules_L1024']:,}); the per-cell statistics timed at four (L, K) points, " + ", ".join(f"L = {q['L']}, K = {q['K']}: {q['seconds']} s (red–green) / {g_['seconds']} s (Gumbel)" for q, g_ in zip(pts['kgw'], pts['gumbel'])) + f", fit seconds = a·nnz + b·N·K + c with a = {cf['kgw']['a_per_nnz']:.2e}, b = {cf['kgw']['b_per_NK']:.2e}, c = {cf['kgw']['c']:.2f} (red–green; largest relative residual {100 * cf['kgw']['max_rel_residual']:.1f}%) and a = {cf['gumbel']['a_per_nnz']:.2e}, b = {cf['gumbel']['b_per_NK']:.2e}, c = {cf['gumbel']['c']:.2f} (Gumbel; {100 * cf['gumbel']['max_rel_residual']:.1f}%); peak resident memory of the validator {rs['peak_rss_gb']} GiB. **Projection (computed from the key-free sizes of every production chain in `INPUTS.json` with these rates; an extrapolation with margin, not a guarantee):** {proj}; budget 10 h. **The runner itself** on a production-sized synthetic chain of the largest type (N = {pb['N']:,}, K = {pb['K']:,}, h = 4, five lengths, three rules, both families: {pb['n_cells']} cells, |D| = {pb['n_tuples']:,}) took {pb['seconds']} s against the {pj['runner_probe_vs_projection']['projected_seconds_largest_chain_type'][0]:.0f} s projected for that chain type (ratio {pj['runner_probe_vs_projection']['ratio_probe_over_projection'][0]}); the process peak resident memory was {pb['peak_rss_gb_process']} GiB (`ru_maxrss`; the validator's earlier sections included; the runner's own peak is at most that). Scaling every chain's projection by the probe's ratio gives **{pj['N%d_K%d' % (pb['N'], pb['K'])]['hours'] * pj['runner_probe_vs_projection']['ratio_probe_over_projection'][0]:.1f} h** for D8's setting, the figure the budget is judged against.")
if pw.get("by_N"):
    parts = []
    for Nx, b in pw["by_N"].items():
        parts.append(f"N = {int(Nx):,}: {b['primary_eligible']} of {b['primary_candidates']} primary cells eligible (by width " + ", ".join(f"h = {h}: {e}/{b['primary_candidates_by_h'][h]}" for h, e in b['primary_eligible_by_h'].items()) + "; by rule " + ", ".join(f"{r}: {e}" for r, e in b['primary_eligible_by_rule'].items()) + "; by tokenizer " + ", ".join(f"{t}: {e}" for t, e in b['primary_eligible_by_tokenizer'].items()) + f"; predicted SD of the eligible cells {b['predicted_sd_pp_primary_eligible_range'][0]:.2f}–{b['predicted_sd_pp_primary_eligible_range'][1]:.2f} pp" + f"; h = 0 KGW cells eligible {b['h0_kgw_g0.25_eligible']}; Gumbel raw/distinct eligible {b['gumbel_raw_distinct_eligible']} of {b['gumbel_raw_distinct_candidates']})")
    kc = pw["key_count"]
    dd = pw.get("dead_detector_flaggable_cells", {}).get(str(N or 10000), {})
    lines.append("**(i) Power (from the key-free inputs; a cell is eligible when mean M ≥ 30 and the theory share ≥ 0.75 at α = 0.01).** " + "; ".join(parts) + f". S2's dead-detector condition at K = {dd.get('K')} (exact key-mean above {dd.get('mu_threshold', 0):.5f}) holds at α = 0.01 in {dd.get('kgw_distinct_cells_flaggable_dead_at_alpha_0.01')} of {dd.get('kgw_distinct_cells')} KGW distinct-rule cells and in {dd.get('gumbel_distinct_cells_flaggable_dead_at_alpha_0.01')} of {dd.get('gumbel_distinct_cells')} Gumbel cells (N = {int(N or 10000):,}). Key count: " + "; ".join(f"K = {Kx}: relative SE of an SD {100 * t['relative_se_of_sd_normal_benchmark']:.1f}% (normal benchmark), ratio interval half-width about {100 * t['ratio_interval_halfwidth_approx']:.1f}%, S4/S5 tolerance about {100 * t['S4_S5_tolerance_relative_approx']:.0f}% of the SD, the 99% key quantile {t['quantile_0.99_rank']}" for Kx, t in kc.items()) + ".")
print("\n\n".join(lines))
